attributes:
{"accept": ""image/jpeg,image/png,image/webp"", "aria-label": ""选择头像图片"", "disabled": "{blocked || !snapshot}", "onChange": "{event => {
      const chosen = event.target.files?.[0] || null;
      if (chosen && (chosen.size > 2 * 1024 * 1024 || !["image/jpeg", "image/png", "image/webp"].includes(chosen.type))) { setFile(null); setPreview(""); setMessage("请选择2 MB以内的JPEG、PNG或WebP。"); event.target.value = ""; return; }
      setFile(chosen); setMessage(""); setPreview("");
    }}", "type": ""file""}

{"disabled": "{blocked}", "onClick": "{async () => {
      if (busyRef.current||blocked) return;
      busyRef.current = true;
      setBusy("reload");
      try { if(hasUnsavedChanges||reviewField.dirty||beforeAction&&!await beforeAction())throw Error("请先保留本页未保存的填写，再读取已保存结果。"); await onAccepted?.(); setRefreshFailed(false); setOutcome(`${label}已保存，页面结果已重新读取。尚未正式发布。`); }
      catch (reason) { setOutcome(reason instanceof Error ? reason.message : "页面读取失败，请稍后重试。"); }
      finally { busyRef.current = false; setBusy(""); }
    }}", "type": ""button""}

{"disabled": "{blocked || (editingClaim?.key === review.key && !editingClaim.proposition.trim())}", "onClick": "{() => {
          if ((!review.enrichment && !review.claim) || (review.enrichment && onFillSuggestion)) choose(review, true);
          else void adopt(review, editingClaim?.key === review.key ? editingClaim.proposition.trim() : undefined);
        }}", "type": ""button""}

{"disabled": "{disabled || !chosen.length || !reviewed || full}", "onClick": "{() => {
      onAppend(chosen.map(candidate => ({ id: null, article_work_id: null, title: candidate.title, author_display: "", page_range: candidate.printed_label, candidate_source: candidate.candidate_source })));
      setSelected([]); setReviewed(false); setMessage("已追加到下方草稿，请补齐作者和终止页，再保存本页填写。");
    }}", "type": ""button""}

{"aria-label": ""更换阅读版本"", "onChange": "{async event => {
              const version = versions.find(row => row.id === event.target.value);
              if (!version || version.id === work.editionId || !(await canLeave())) return;
              const url = version.readable_asset ? `/reader/${encodeURIComponent(version.readable_asset.id)}` : `/works/${encodeURIComponent(version.public_slug || version.id)}`;
              router.push(researchReturn && version.readable_asset ? `${url}?${new URLSearchParams({ return_to: researchReturn })}` : url);
            }}", "value": "{work.editionId}"}

{"disabled": "{disabled || !ready}", "onClick": "{() => {
        if (!target || !ready) return;
        setOpen(false); void onTransfer({ target: target.id, target_version: target.version, acknowledge_remote: target.external && acknowledged });
      }}", "type": ""button""}

{"name": "{`evaluation_relevance_${index}`}", "onChange": "{(event) => {
                      const value = event.target.value;
                      setEvaluationJudgments((current) => {
                        if (value === "") {
                          const next = { ...current };
                          delete next[item.id];
                          return next;
                        }
                        return { ...current, [item.id]: Number(value) };
                      });
                    }}", "value": "{evaluationJudgments[item.id] ?? ""}"}

{"checked": "{checked}", "disabled": "{locked || (!checked && selected.length >= (policy?.item_count || 4))}", "onChange": "{() => {
              setSelectionLabels((current) => ({ ...current, [item.id]: label }));
              updateSelected((current) => checked ? current.filter((id) => id !== item.id) : current.length < (policy?.item_count || 4) ? current.concat(item.id) : current);
            }}", "type": ""checkbox""}

{"onChange": "{(event) => {
                  const next = [...rows];
                  next[index] = event.target.value;
                  onChange(next);
                }}", "placeholder": "{placeholder}", "required": "{required && index === 0}", "value": "{item}"}

{"onClick": "{() => onChange(
                active
                  ? selected.filter((id) => id !== option.id)
                  : single ? [option.id] : selected.concat(option.id),
              )}", "type": ""button""}

{"max": ""999999"", "min": ""1"", "onChange": "{event => {
      const page = Number(event.target.value);
      if (Number.isInteger(page) && page > 0 && page <= 999999) onChange(`${publicPath.split("?", 1)[0]}?page=${page}`, title || source.source?.title);
    }}", "type": ""number"", "value": "{new URLSearchParams(publicPath.split("?")[1] || "").get("page") || "1"}"}

{"onSubmit": "{event => {
      event.preventDefault();
      const next = feedbackPathFromInput(String(new FormData(event.currentTarget).get("source") || ""), window.location.origin);
      if (!next) { setInputError("请粘贴本站公开页面地址或路径，不支持账户资料、后台或外部链接。"); return; }
      setInputError(""); router.push(`/help/source?${new URLSearchParams({ source: next })}`);
    }}"}
